import{_ as t,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"止观","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-止观.md","filePath":"50-概念资料/dict-止观.md","lastUpdated":1778040484000}'),r={name:"50-概念资料/dict-止观.md"};function i(n,a,u,d,c,h){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="止观" tabindex="-1">止观 <a class="header-anchor" href="#止观" aria-label="Permalink to &quot;止观&quot;">​</a></h1><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>止观是佛教禅修的两大核心：<strong>止</strong>是令心安住于一处，<strong>观</strong>是观察思惟实相。了空居士的独特之处在于他强调<strong>止观一体</strong>——止中有观，观中有止。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;似守非守——不可用心守，不可无意求。守得太紧就着相，守得太松就无效。&quot;</p></blockquote><blockquote><p>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</p></blockquote><blockquote><p>&quot;照见五蕴皆空——清清楚楚地明白五蕴都是不永恒的。照就是观，清楚地明白就是止。&quot;</p></blockquote><h2 id="了空居士的独特诠释" tabindex="-1">了空居士的独特诠释 <a class="header-anchor" href="#了空居士的独特诠释" aria-label="Permalink to &quot;了空居士的独特诠释&quot;">​</a></h2><p>传统天台宗讲&quot;次第止观&quot;——先修止再修观。了空居士的路线更接近禅宗的&quot;圆顿止观&quot;——<strong>止和观是同时的</strong>。当你知道自己在打妄想（观），你就已经在了了分明（止）的状态。</p><blockquote><p>知道杂念的那一刹那，你已经不在杂念中了。这个&quot;知道&quot;本身就是止观同时。</p></blockquote><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-观照">观照</a> — 了空居士体系中的观照即止观合一</li><li><a href="/50-概念资料/dict-清净心">清净心</a> — 止观达到的心状态</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 止观的生活应用</li><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 止观在功法中的应用</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不必把止观想得太复杂</li><li>知道自己在做什么——吃饭时知道在吃饭，走路时知道在走路</li><li>知道了，就已经在止观中了</li></ul>',16)])])}const p=t(r,[["render",i]]);export{q as __pageData,p as default};
